SELECT br.*, b.name AS book_title, u.username AS username FROM borrow_record br LEFT JOIN book b ON br.book_id = b.id LEFT JOIN user u ON br.user_id = u.id
AND br.user_id = #{dto.userId}
AND br.status = #{dto.status}
ORDER BY br.borrow_time DESC LIMIT #{offset}, #{pageSize}

